(() => {
 const $=id=>document.getElementById(id),key='animal-post-office-teacher-lessons-v1';let saved=[];try{saved=JSON.parse(localStorage.getItem(key)||'[]');if(!Array.isArray(saved))saved=[];saved=saved.map(PostLesson.validate);}catch{saved=[];}
 let category=PostVocabulary.categories[0].name;
 function renderCategories(){$('category-picker').replaceChildren(...PostVocabulary.categories.map(group=>{const button=document.createElement('button');button.type='button';button.textContent=group.name+' · 20 pictures';button.setAttribute('aria-pressed',String(group.name===category));button.onclick=()=>{category=group.name;renderCategories();};return button;}));for(const label of $('word-picker').querySelectorAll('label'))label.hidden=label.dataset.category!==category;$('category-heading').textContent=category;}
 function fill(config){const c=PostLesson.validate(config);$('lesson-title').value=c.title;$('lesson-stage').value=c.stage;for(const [id,values,selection] of [['letter-picker',[...'ABCDEFGHIJKLMNOPQRSTUVWXYZ'],[...c.letters]],['word-picker',PostLesson.words,c.words]]){$(id).replaceChildren(...values.map(value=>{const label=document.createElement('label'),input=document.createElement('input'),span=document.createElement('span');input.type='checkbox';input.value=value;input.checked=selection.includes(value);span.textContent=value;label.append(input);if(id==='word-picker'){const item=PostVocabulary.items.find(x=>x.name===value),picture=document.createElement('span');picture.className='word-picture';picture.innerHTML=item.svg;picture.setAttribute('aria-hidden','true');label.dataset.category=item.category;label.append(picture);}label.append(span);return label;}));}renderCategories();count();}
 function read(){return PostLesson.validate({title:$('lesson-title').value,stage:Number($('lesson-stage').value),letters:[...$('letter-picker').querySelectorAll('input:checked')].map(x=>x.value),words:[...$('word-picker').querySelectorAll('input:checked')].map(x=>x.value)});}
 function count(){$('selection-count').textContent=$('letter-picker').querySelectorAll('input:checked').length+' letters · '+$('word-picker').querySelectorAll('input:checked').length+' picture words selected';}
 function action(fn){try{$('message').textContent='';fn(read());}catch(error){$('message').textContent=error.message;}}
 function renderSaved(){$('saved-lessons').replaceChildren(...saved.map((c,index)=>{const row=document.createElement('div'),title=document.createElement('strong'),load=document.createElement('button'),remove=document.createElement('button');row.className='saved-row';title.textContent=c.title;load.type=remove.type='button';load.textContent='Edit lesson';remove.textContent='Remove';load.onclick=()=>{fill(c);$('message').textContent='Loaded '+c.title;};remove.onclick=()=>{const next=saved.filter((_,i)=>i!==index);try{localStorage.setItem(key,JSON.stringify(next));saved=next;renderSaved();}catch{$('message').textContent='Your browser could not save changes.';}};row.append(title,load,remove);return row;}));if(!saved.length)$('saved-lessons').textContent='No saved lessons yet. Saved lessons stay on this device.';}
 $('lesson-form').onchange=count;for(const kind of ['letters','words'])for(const all of [true,false])$(all?'all-'+kind:'clear-'+kind).onclick=()=>{$(kind==='letters'?'letter-picker':'word-picker').querySelectorAll('input').forEach(x=>x.checked=all);count();};
 for(const [id,checked] of [['select-category',true],['clear-category',false]])$(id).onclick=()=>{$('word-picker').querySelectorAll('label').forEach(label=>{if(label.dataset.category===category)label.querySelector('input').checked=checked;});count();};
 $('lesson-form').onsubmit=e=>{e.preventDefault();action(c=>{location.href='index.html#lesson='+encodeURIComponent(JSON.stringify(c));});};
 $('save').onclick=()=>action(c=>{const next=[...saved.filter(x=>x.title!==c.title),c];localStorage.setItem(key,JSON.stringify(next));saved=next;renderSaved();$('message').textContent='Lesson saved on this device.';});
 $('download').onclick=()=>action(c=>{const url=URL.createObjectURL(new Blob([JSON.stringify({schemaVersion:1,game:'animal-post-office',lesson:c},null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='animal-post-office-lesson.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
 $('import').onchange=async()=>{try{const file=$('import').files[0];if(!file)return;if(file.size>100000)throw Error('That lesson file is too large.');const data=JSON.parse(await file.text());if(data.game!=='animal-post-office'||data.schemaVersion!==1)throw Error('Import an Animal Post Office lesson file.');fill(data.lesson);$('message').textContent='Lesson imported. Save it or play now.';}catch(error){$('message').textContent=error.message;}finally{$('import').value='';}};
 let initial=PostLesson.defaults();try{const raw=new URLSearchParams(location.hash.slice(1)).get('lesson');if(raw)initial=PostLesson.validate(JSON.parse(raw));}catch(error){$('message').textContent='Lesson link could not be read: '+error.message;}fill(initial);renderSaved();
})();
